    // 2. Extraer inteligentemente solo el SLUG (Ignorando fechas 2026/08)
    var rutaDecodificada = "";
    try { rutaDecodificada = decodeURIComponent(window.location.pathname + window.location.search); } 
    catch(e) { rutaDecodificada = window.location.pathname + window.location.search; }

    var match = rutaDecodificada.match(/\/([^\/]+)(?:\.html)?$/i);
    var slugRoto = match ? match[1] : rutaDecodificada;

    // Limpieza profunda
    var textoUrl = slugRoto.toLowerCase()
                       .replace(/[?&]m=[01]/g, " ") 
                       .replace(/%20/g, " ")
                       .replace(/[\/\-_?&+=]/g, " ")
                       .replace(/\b(html|php|xml)\b/g, ""); 

    var terminoBusqueda = normalizarTexto(textoUrl).trim();
    var palabrasBusqueda = terminoBusqueda.split(" ").filter(p => p.length > 2);

    if (terminoBusqueda !== "") {
        var mejorEnlace = "/"; 
        var maxCoincidencias = 0;

        // 3. Evaluar Enlaces Dinámicos (Sistema de Scoring Semántico)
        for (var i = 0; i < enlaces.length; i++) {
            var keywords = enlaces[i].keywords;
            var coincidenciasActuales = 0;
            
            for (var j = 0; j < keywords.length; j++) {
                var kw = normalizarTexto(keywords[j]);
                
                for(var p = 0; p < palabrasBusqueda.length; p++) {
                    var pb = palabrasBusqueda[p];
                    if (pb === kw || (kw.length > 3 && pb.includes(kw)) || (pb.length > 3 && kw.includes(pb))) {
                        coincidenciasActuales++;
                    }
                }
            }
            
            // Actualizamos si este enlace tiene más palabras en común con la URL rota
            if (coincidenciasActuales > maxCoincidencias) {
                maxCoincidencias = coincidenciasActuales;
                mejorEnlace = enlaces[i].url;
            }
        }

        // 4. Evaluar Enlaces Estáticos de Respaldo (Si el dinámico falla)
        if (maxCoincidencias === 0) {
             for (var k = 0; k < enlacesEstaticos.length; k++) {
                 var kwEst = normalizarTexto(enlacesEstaticos[k].keywords[0]);
                 if (terminoBusqueda.includes(kwEst) || kwEst.includes(terminoBusqueda)) {
                     mejorEnlace = enlacesEstaticos[k].url;
                     break;
                 }
             }
        }

        // 5. Ejecutar redirección
        if (mejorEnlace && mejorEnlace !== window.location.href) {
            window.location.replace(mejorEnlace);
        }
    }
